/* =============================================
   GUEST PAGES — Unified Design System
   (login, first_login, forgot_password, reset_password,
    set_password, verify_otp, verify_2fa)
   ============================================= */

/* ---------- Reset & Base ---------- */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
    --g-navy-deep: #0a1628;
    --g-navy: #111d3a;
    --g-navy-mid: #162450;
    --g-blue: #1a237e;
    --g-blue-bright: #2962ff;
    --g-blue-sky: #448aff;
    --g-accent: #64b5f6;
    --g-white: #f8fafc;
    --g-card: #ffffff;
    --g-text: #1e293b;
    --g-muted: #64748b;
    --g-border: #e2e8f0;
    --g-radius: 14px;
    --g-radius-sm: 10px;
    --g-font: 'Sarabun', sans-serif;
    --g-ease: cubic-bezier(0.16, 1, 0.3, 1);
}

body {
    font-family: var(--g-font);
    min-height: 100vh;
    background: var(--g-navy-deep);
    color: var(--g-text);
    -webkit-font-smoothing: antialiased;
}

/* ---------- Split Layout ---------- */
.guest-split {
    display: flex;
    min-height: 100vh;
}

/* Brand Panel (left side on desktop) */
.guest-brand {
    flex: 0 0 420px;
    background: linear-gradient(160deg, var(--g-navy-deep) 0%, var(--g-navy) 35%, var(--g-navy-mid) 100%);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 48px 40px;
    position: relative;
    overflow: hidden;
}

/* Subtle grid pattern overlay */
.guest-brand::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}

/* Accent glow */
.guest-brand::after {
    content: '';
    position: absolute;
    bottom: -80px;
    left: -80px;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(41,98,255,0.12) 0%, transparent 70%);
    pointer-events: none;
}

.guest-brand-logo {
    width: 88px;
    height: 88px;
    border-radius: 20px;
    object-fit: contain;
    background: var(--g-card);
    padding: 10px;
    margin-bottom: 24px;
    box-shadow: 0 8px 32px rgba(0,0,0,0.3);
    position: relative;
    z-index: 1;
}

.guest-brand-title {
    color: var(--g-white);
    font-size: 1.25rem;
    font-weight: 700;
    text-align: center;
    line-height: 1.5;
    max-width: 320px;
    position: relative;
    z-index: 1;
}

.guest-brand-sub {
    color: var(--g-accent);
    font-size: 0.85rem;
    margin-top: 8px;
    opacity: 0.85;
    position: relative;
    z-index: 1;
}

/* Form Panel (right side on desktop) */
.guest-form {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px 24px;
    background: var(--g-white);
    position: relative;
    overflow-y: auto;
}

/* ---------- Guest Card ---------- */
.guest-card {
    width: 100%;
    max-width: 420px;
    animation: guestCardIn 0.6s var(--g-ease) both;
}

@keyframes guestCardIn {
    from { opacity: 0; transform: translateY(20px); }
    to   { opacity: 1; transform: translateY(0); }
}

.guest-card-heading {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--g-navy);
    margin-bottom: 4px;
}

.guest-card-sub {
    color: var(--g-muted);
    font-size: 0.9rem;
    margin-bottom: 28px;
    line-height: 1.6;
}

/* ---------- Form Elements ---------- */
.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--g-text);
    margin-bottom: 6px;
}

.input-wrapper {
    position: relative;
}

.input-wrapper i {
    position: absolute;
    left: 14px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--g-muted);
    font-size: 15px;
    transition: color 0.2s;
}

.input-wrapper input:focus ~ i,
.input-wrapper input:focus + i { /* fallback for siblings */ }

.form-group input,
.guest-input {
    width: 100%;
    padding: 12px 14px 12px 42px;
    border: 2px solid var(--g-border);
    border-radius: var(--g-radius-sm);
    font-family: var(--g-font);
    font-size: 0.95rem;
    color: var(--g-text);
    transition: border-color 0.25s, box-shadow 0.25s;
    outline: none;
    background: var(--g-card);
}

.form-group input:focus,
.guest-input:focus {
    border-color: var(--g-blue);
    box-shadow: 0 0 0 3px rgba(26, 35, 126, 0.08);
}

.form-group input:focus + i {
    color: var(--g-blue);
}

/* ---------- Buttons ---------- */
.btn-guest-primary {
    width: 100%;
    padding: 13px;
    border: none;
    border-radius: var(--g-radius-sm);
    background: linear-gradient(135deg, var(--g-navy) 0%, var(--g-blue) 100%);
    color: #fff;
    font-family: var(--g-font);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: transform 0.2s var(--g-ease), box-shadow 0.2s var(--g-ease);
    margin-top: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.btn-guest-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 24px rgba(26, 35, 126, 0.3);
}

.btn-guest-primary:active {
    transform: translateY(0);
}

.btn-guest-primary:disabled {
    background: #cbd5e1;
    cursor: not-allowed;
    transform: none;
    box-shadow: none;
}

.btn-guest-secondary {
    width: 100%;
    padding: 12px;
    border: 2px solid var(--g-navy);
    border-radius: var(--g-radius-sm);
    background: transparent;
    color: var(--g-navy);
    font-family: var(--g-font);
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.25s;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    text-decoration: none;
}

.btn-guest-secondary:hover {
    background: var(--g-navy);
    color: #fff;
}

/* ---------- Divider ---------- */
.guest-divider {
    text-align: center;
    margin: 22px 0;
    position: relative;
}

.guest-divider::before,
.guest-divider::after {
    content: '';
    position: absolute;
    top: 50%;
    width: 40%;
    height: 1px;
    background: var(--g-border);
}

.guest-divider::before { left: 0; }
.guest-divider::after { right: 0; }

.guest-divider span {
    background: var(--g-white);
    padding: 0 14px;
    color: var(--g-muted);
    font-size: 0.82rem;
    position: relative;
}

/* ---------- Alerts ---------- */
.alert {
    padding: 12px 16px;
    border-radius: var(--g-radius-sm);
    margin-bottom: 20px;
    font-size: 0.88rem;
    display: flex;
    align-items: center;
    gap: 10px;
    animation: alertIn 0.35s var(--g-ease) both;
}

@keyframes alertIn {
    from { opacity: 0; transform: translateY(-6px); }
    to   { opacity: 1; transform: translateY(0); }
}

.alert-success {
    background: #ecfdf5;
    color: #065f46;
    border: 1px solid #a7f3d0;
}

.alert-danger {
    background: #fef2f2;
    color: #991b1b;
    border: 1px solid #fecaca;
}

.alert-warning {
    background: #fffbeb;
    color: #92400e;
    border: 1px solid #fde68a;
}

/* ---------- Links ---------- */
.guest-link {
    text-align: center;
    margin-top: 18px;
}

.guest-link a {
    color: var(--g-blue);
    text-decoration: none;
    font-size: 0.88rem;
    font-weight: 500;
    transition: color 0.2s;
}

.guest-link a:hover {
    color: var(--g-blue-bright);
    text-decoration: underline;
}

/* ---------- Footer ---------- */
.guest-footer {
    text-align: center;
    margin-top: 32px;
    color: var(--g-muted);
    font-size: 0.78rem;
}

/* In brand panel context */
.guest-brand .guest-footer {
    position: absolute;
    bottom: 24px;
    left: 0;
    right: 0;
    color: rgba(255,255,255,0.35);
}

/* ---------- Step Indicator ---------- */
.guest-steps {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    margin-bottom: 28px;
}

.guest-step {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.82rem;
    color: var(--g-muted);
    font-weight: 500;
}

.guest-step-num {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.78rem;
    font-weight: 700;
    border: 2px solid var(--g-border);
    background: transparent;
    color: var(--g-muted);
    transition: all 0.3s;
    flex-shrink: 0;
}

.guest-step-connector {
    width: 32px;
    height: 2px;
    background: var(--g-border);
    margin: 0 6px;
    transition: background 0.3s;
}

.guest-step.gs-active .guest-step-num {
    background: var(--g-blue);
    border-color: var(--g-blue);
    color: #fff;
    box-shadow: 0 2px 8px rgba(26, 35, 126, 0.25);
}

.guest-step.gs-active {
    color: var(--g-navy);
    font-weight: 600;
}

.guest-step.gs-done .guest-step-num {
    background: #059669;
    border-color: #059669;
    color: #fff;
}

.guest-step.gs-done {
    color: #059669;
}

.guest-step.gs-done ~ .guest-step-connector,
.guest-step.gs-done + .guest-step-connector {
    background: #059669;
}

/* Connector after done step turns green */
.gs-connector-done {
    background: #059669 !important;
}

/* ---------- Password Rules ---------- */
.pw-rules {
    background: #f1f5f9;
    padding: 14px 16px;
    border-radius: var(--g-radius-sm);
    margin-bottom: 20px;
    border: 1px solid var(--g-border);
}

.pw-rules-title {
    font-size: 0.82rem;
    color: var(--g-muted);
    margin-bottom: 8px;
    font-weight: 600;
}

.pw-rules-title i {
    margin-right: 4px;
}

.pw-rules ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.pw-rules ul li {
    font-size: 0.82rem;
    color: #94a3b8;
    padding: 3px 0;
    transition: color 0.2s;
}

.pw-rules ul li i {
    margin-right: 6px;
    font-size: 0.7rem;
    width: 14px;
    text-align: center;
}

.pw-rules ul li.valid {
    color: #059669;
}

.pw-rules ul li.valid i::before {
    content: "\f058"; /* fa-check-circle */
}

/* Strength meter */
.pw-strength {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 12px;
}

.pw-strength-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--g-muted);
    white-space: nowrap;
}

.pw-strength-track {
    flex: 1;
    height: 6px;
    background: var(--g-border);
    border-radius: 3px;
    overflow: hidden;
}

.pw-strength-bar {
    height: 100%;
    width: 0;
    border-radius: 3px;
    transition: width 0.3s, background 0.3s;
}

.pw-strength-value {
    font-size: 0.78rem;
    font-weight: 600;
    white-space: nowrap;
    color: var(--g-muted);
    min-width: 60px;
    text-align: right;
}

/* Match status */
.pw-match {
    text-align: center;
    font-size: 0.82rem;
    margin-top: -8px;
    margin-bottom: 16px;
    height: 20px;
    transition: color 0.2s;
}

.pw-match.match { color: #059669; }
.pw-match.no-match { color: #dc2626; }

/* ---------- OTP Input ---------- */
.otp-input-single {
    width: 100%;
    padding: 15px;
    border: 2px solid var(--g-border);
    border-radius: var(--g-radius-sm);
    font-family: var(--g-font);
    font-size: 1.75rem;
    font-weight: 700;
    text-align: center;
    letter-spacing: 8px;
    color: var(--g-navy);
    transition: border-color 0.25s;
    outline: none;
    background: var(--g-card);
}

.otp-input-single:focus {
    border-color: var(--g-blue);
    box-shadow: 0 0 0 3px rgba(26, 35, 126, 0.08);
}

/* OTP Grid (individual boxes) */
.otp-grid {
    display: flex;
    gap: 8px;
    justify-content: center;
    margin: 24px 0;
}

.otp-cell {
    width: 46px;
    height: 54px;
    text-align: center;
    font-size: 1.25rem;
    font-weight: 700;
    font-family: var(--g-font);
    border: 2px solid var(--g-border);
    border-radius: 10px;
    outline: none;
    transition: all 0.2s;
    color: var(--g-navy);
    background: var(--g-card);
}

.otp-cell:focus {
    border-color: var(--g-blue);
    box-shadow: 0 0 0 3px rgba(26, 35, 126, 0.1);
    transform: scale(1.05);
}

.otp-cell.filled {
    border-color: #059669;
    background: #f0fdf4;
}

/* OTP Info badge */
.otp-info {
    text-align: center;
    margin: 16px 0;
    padding: 10px 16px;
    background: #f1f5f9;
    border-radius: 8px;
    font-size: 0.82rem;
    color: var(--g-muted);
}

.otp-info i {
    color: var(--g-blue);
    margin-right: 6px;
}

/* Email badge */
.email-badge {
    display: inline-block;
    background: #eff6ff;
    color: var(--g-blue);
    padding: 4px 14px;
    border-radius: 20px;
    font-weight: 600;
    font-size: 0.88rem;
}

/* ---------- Resend Section ---------- */
.resend-section {
    text-align: center;
    margin-top: 22px;
    padding-top: 18px;
    border-top: 1px solid var(--g-border);
}

.resend-section p {
    font-size: 0.88rem;
    color: var(--g-muted);
    margin-bottom: 10px;
}

.btn-resend {
    background: none;
    border: 2px solid var(--g-navy);
    border-radius: var(--g-radius-sm);
    color: var(--g-navy);
    padding: 10px 22px;
    font-family: var(--g-font);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.25s;
}

.btn-resend:hover {
    background: var(--g-navy);
    color: #fff;
}

.btn-resend:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    border-color: #cbd5e1;
    color: #cbd5e1;
}

.btn-resend:disabled:hover {
    background: none;
    color: #cbd5e1;
}

.countdown-badge {
    display: inline-block;
    background: #fffbeb;
    color: #92400e;
    padding: 6px 16px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 600;
    margin-top: 12px;
}

/* ---------- Lockout Countdown ---------- */
.lockout-timer {
    display: none;
    margin-top: 8px;
    font-weight: 700;
    color: #dc2626;
    font-size: 0.88rem;
}

/* ---------- Language Dropdown ---------- */
.lang-dropdown {
    position: fixed;
    top: 18px;
    right: 18px;
    z-index: 1000;
}

.lang-dropdown-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,255,255,0.1);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255,255,255,0.18);
    color: #fff;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 8px 14px;
    border-radius: var(--g-radius-sm);
    transition: background 0.2s;
    font-family: var(--g-font);
}

.lang-dropdown-btn:hover {
    background: rgba(255,255,255,0.2);
}

.lang-dropdown-btn .lang-icon {
    font-size: 1.15rem;
    color: var(--g-accent);
}

.lang-dropdown-menu {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    min-width: 140px;
    background: var(--g-navy);
    border-radius: 12px;
    box-shadow: 0 8px 28px rgba(0,0,0,0.4);
    padding: 6px 0;
    margin-top: 6px;
    overflow: hidden;
}

.lang-dropdown-menu.show {
    display: block;
    animation: langSlide 0.2s var(--g-ease);
}

@keyframes langSlide {
    from { opacity: 0; transform: translateY(-8px); }
    to   { opacity: 1; transform: translateY(0); }
}

.lang-dropdown-item {
    display: block;
    width: 100%;
    padding: 10px 18px;
    background: none;
    border: none;
    color: rgba(255,255,255,0.85);
    font-size: 0.9rem;
    text-align: left;
    cursor: pointer;
    transition: background 0.15s;
    font-family: var(--g-font);
}

.lang-dropdown-item:hover {
    background: rgba(255,255,255,0.08);
}

.lang-dropdown-item.active {
    color: var(--g-accent);
    font-weight: 600;
}

/* ---------- Google Translate Hidden ---------- */
.goog-te-banner-frame.skiptranslate { display: none !important; }
body { top: 0px !important; }
.goog-te-gadget { font-size: 0 !important; }
.skiptranslate { display: none !important; }
#google_translate_element {
    position: absolute;
    top: -9999px;
    left: -9999px;
    width: 0;
    height: 0;
    overflow: hidden;
}

/* ---------- Responsive ---------- */
@media (max-width: 767px) {
    .guest-split {
        flex-direction: column;
    }

    .guest-brand {
        flex: 0 0 auto;
        padding: 32px 24px 24px;
    }

    .guest-brand::after {
        display: none;
    }

    .guest-brand-logo {
        width: 64px;
        height: 64px;
        margin-bottom: 14px;
    }

    .guest-brand-title {
        font-size: 1rem;
    }

    .guest-form {
        padding: 28px 20px;
        border-radius: 24px 24px 0 0;
        margin-top: -16px;
        position: relative;
        z-index: 1;
    }

    .guest-card {
        max-width: 100%;
    }

    .guest-card-heading {
        font-size: 1.3rem;
    }

    .lang-dropdown {
        top: 12px;
        right: 12px;
    }

    .otp-grid {
        gap: 5px;
    }

    .otp-cell {
        width: 38px;
        height: 48px;
        font-size: 1.1rem;
    }
}

@media (min-width: 768px) and (max-width: 1024px) {
    .guest-brand {
        flex: 0 0 320px;
        padding: 40px 28px;
    }
}
